/// <summary>
/// Creates new inventory modules for the product variant that is being released.
/// </summary>
[Wrappable(true)]   
internal void postRelease()
{
    EcoResDistinctProductVariant distinctProductVariant = ecoResProduct as EcoResDistinctProductVariant;

    next postRelease();

    /// Create inventory modules for the newly created product variant.
    EcoResProductVariantManager::createInventTableModules_AVA(distinctProductVariant.RecId);
}
